import java.util.Scanner;

public class Main10 {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int number = scanner.nextInt();
        String inputStr = scanner.next();
        String tempStr = inputStr;
        String bracketsContent = "_";
        int startIdx = -1;
        int totalLength = tempStr.length();

        for (int index = 0; index < totalLength; index++) {
            char ch = tempStr.charAt(index);
            if (ch == '(') {
                startIdx = index;
            } else if (ch == ')') {
                bracketsContent += tempStr.substring(startIdx + 1, index) + "_";
                tempStr = tempStr.substring(0, startIdx) + "_" + tempStr.substring(index + 1);
                totalLength = tempStr.length();
                index = startIdx - 1;
                startIdx = -1;
            }
        }
        String[] bracketParts = bracketsContent.split("_");
        int bracketCount = 0;
        for (String part : bracketParts) {
            if (!part.isEmpty()) {
                bracketCount++;
            }
        }
        String[] segmentsArray = tempStr.split("_");
        int maxSegmentLength = 0;
        for (String segment : segmentsArray) {
            if (segment.length() > maxSegmentLength) {
                maxSegmentLength = segment.length();
            }
        }
        System.out.println(maxSegmentLength + " " + bracketCount);
    }
}
